// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 blockNum, uint256 timestamp) public {
        // bound timestamp to be reasonably after current block time
        vm.assume(timestamp > block.timestamp);
        // set block number modulo 15 to be able to trigger the transfer if needed
        vm.assume(blockNum % 15 != 0); // avoid transfer for simplicity
        vm.warp(timestamp);
        vm.roll(blockNum);
        // Ensure we have enough balance for the call
        vm.deal(address(c), 20 ether);
        uint256 pastBefore = c.pastBlockTime();
        // Make the fallback call with exactly 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");
        // Assert that after call, either it reverted (if timestamp <= pastBefore) or pastBlockTime increased
        if (success) {
            uint256 pastAfter = c.pastBlockTime();
            assertTrue(pastAfter > pastBefore);
        }
    }
}

